function stripComments(src){let out="",depth=0,str=false;for(let i=0;i<src.length;){let a=src[i],b=src[i+1];if(depth){if(a==="/"&&b==="-"){depth++;out+="  ";i+=2;}else if(a==="-"&&b==="/"){depth--;out+="  ";i+=2;}else{out+=a==="\n"?"\n":" ";i++;}}else if(str){out+=a;i++;if(a==="\\"&&i<src.length){out+=src[i++];}else if(a==='"')str=false;}else if(a==='"'){str=true;out+=a;i++;}else if(a==="/"&&b==="-"){depth=1;out+="  ";i+=2;}else if(a==="-"&&b==="-"){while(i<src.length&&src[i]!=="\n"){out+=" ";i++;}}else{out+=a;i++;}}return out;}
function scanLean(src){const text=stripComments(src),lines=text.split("\n"),stack=[],decls=[],warnings=[];let ns="",offset=0;
 for(let i=0;i<lines.length;i++){const line=lines[i],trim=line.trim();let m;
 if((m=trim.match(/^namespace\s+([^\s]+)/))){stack.push({kind:"namespace",name:m[1],old:ns});ns=m[1].startsWith("_root_.")?m[1].slice(7):(ns?ns+".":"")+m[1];}
 else if((m=trim.match(/^section(?:\s+([^\s]+))?\s*$/))){stack.push({kind:"section",name:m[1]||null,old:ns});}
 else if(/^end(?:\s+[^\s]+)?\s*$/.test(trim)){if(stack.length){const v=stack.pop();ns=v.old;}else warnings.push({line:i+1,kind:"unmatched-end",text:trim});}
 const clean=trim.replace(/^(?:@\[[^\]]*\]\s*)+/,"");
 m=clean.match(/^((?:(?:private|protected|noncomputable|unsafe|partial|local)\s+)*)(theorem|lemma|def|abbrev|opaque|structure|class|inductive|instance)\s+([^\s:(\[{]+)/);
 if(m){const mods=m[1],kind=m[2],name=m[3];if(!/\bprivate\b|\blocal\b/.test(mods)&&!(kind==="instance"&&/^[:({\[]/.test(name))){const full=name.startsWith("_root_.")?name.slice(7):(ns?ns+".":"")+name;const start=offset+line.indexOf(m[0]);const tail=text.slice(start);let end=tail.search(/:=\s*by\b/);if(end<0||!["theorem","lemma"].includes(kind))end=tail.search(/:=|\bwhere\b/);decls.push({name:full,short:name,kind,line:i+1,header:end<0?null:src.slice(start,start+end).trim()});}}
 offset+=line.length+1;}
 return {declarations:decls,warnings};}
